// Extract the MinIO object key from the S3-compatible event payload.
// MinIO sends two payload shapes; handle both:
//   Shape A (top-level Key field): { "Key": "videos/cam01/clip.mp4", ... }
//   Shape B (Records array, S3-compatible): { "Records": [{ "s3": { "object": { "key": "..." } } }] }
const body = $input.first().json.body || $input.first().json;
const key = body.Key || (body.Records && body.Records.length > 0 && body.Records[0].s3 && body.Records[0].s3.object && body.Records[0].s3.object.key);

if (!key) {
  // Payload did not contain a recognisable object key — skip silently
  return [];
}

// Extension filter — same set as ingestion-worker defensive guard
const VIDEO_EXTS = /\.(mp4|mov|avi|mkv)$/i;
if (!VIDEO_EXTS.test(key)) {
  // Not a video file — skip (no HTTP call made)
  return [];
}

return [{ json: { minio_key: key } }];
